// normally, but it opportunistically opens a constrained span after some free-form
// explanation text so arithmetic can be written explicitly inside delimiters.
// Inside constrained spans it uses parser-guided constrained decoding, with
// dead-end detection and rollback-based repair if the constrained prefix becomes
// difficult or invalid to extend.
// The main observations used are delimiter balance in the generated text,
// parser completeness/validity of the current constrained prefix, and simple
// progress conditions such as whether enough steps remain to open or close a
// span. This tracked state supports valid generation by ensuring constrained
// content is only accumulated while inside a span, remains parser-valid when
// possible, and is reset when a span is closed or repaired away.
// CSD_RATIONALE_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant cost == 0
  invariant helpers.cost <= steps
  decreases maxSteps - steps
